import {conciseCue,rewardXP,consecutiveDays} from './learning.js';
import {selectBlueprint} from './syllabus.js';
import {loadProgress,persistProgress} from './storage.js';
import {KEY,fresh,validate,validActive,merge,event,derive,dayKey,legacyValid} from './progress.js';
const B=window.LAWLINGO_BANK,Q=new Map(B.questions.map(q=>[q.id,q])),BOOK=B.questions.filter(q=>q.sourceType==='book');
let state,storageOK=true,view='home',chosenDay=1,summary=null,cancelModal=null,libraryFilter={text:"",subject:"all",status:"all"},syncText='Saved on this device';
let recoveredSave=false;
try{const loaded=loadProgress(localStorage);state=loaded.state;recoveredSave=loaded.recovered}catch{state=fresh();storageOK=false}
try{if(!state.events.some(e=>e.kind==='import')){const legacy=window.LAWLINGO_SEED||JSON.parse(localStorage.getItem('lawlingo-progress-v1')||'null');if(legacyValid(legacy))state.events.push(event('import',legacy))}}catch{}
state.settings||={sound:false};
if(state.active&&!validActive(state.active,id=>Q.has(id)||/^sample-([1-9]|[1-4][0-9]|50)$/.test(id)))state.active=null;
let P=derive(state.events),active=state.active;
let derivedEvents=state.events,derivedCount=state.events.length;
chosenDay=B.lessons.find(l=>!P.lessons.has(l.id))?.day||4;
const main=document.getElementById('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,cls='',attrs='')=>`<button type="button" data-action="${action}" class="${cls}" ${attrs}>${label}</button>`;
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const s=qid=>P.stats[qid]||{seen:0,correct:0,wrong:0,level:0,due:0};
const due=()=>[...Q.values()].filter(q=>s(q.id).seen&&s(q.id).due<=Date.now()&&canAnswer(q));
const weak=()=>[...Q.values()].filter(q=>s(q.id).weak||P.bookmarks.has(q.id));
const sourceLabel=q=>q.sourceType==='book'?`Book · ${q.subject} Q${q.number} · PDF p.${q.page}`:q.sourceType==='sample'?`HEC official sample Q${q.number}`:'Lawlingo foundation drill';
const graded=q=>q.answer!==null&&q.status==='verified';
const mockEligible=q=>graded(q)&&q.mockEligible===true;
const canAnswer=q=>q.answer!==null&&!['disputed','unverified'].includes(q.status);
const percent=(a,b)=>b?Math.round(100*a/b):0;
function mascot(mood=''){return `<button type="button" class="mascot-button" data-action="pet" aria-label="Tap Legalu for a surprise"><svg class="legalu ${mood}" viewBox="0 0 180 180" role="img" aria-label="Legalu, your rooster study companion"><ellipse cx="87" cy="165" rx="43" ry="7" fill="#193e3510"/><g class="leg-body"><path d="M49 116Q10 110 20 86Q31 64 51 109Q10 91 33 71Q52 61 62 106" fill="#377b68"/><path d="M80 52C55 21 86 6 91 33C100 6 123 25 104 51" fill="#ed755c"/><ellipse cx="85" cy="118" rx="44" ry="40" fill="#fff0c9" stroke="#e6d8af" stroke-width="2"/><circle cx="101" cy="70" r="34" fill="#fff0c9" stroke="#e6d8af" stroke-width="2"/><path d="M130 71l26 11-27 10" fill="#edb843"/><path d="M115 100q24 16 0 29q-16-15 0-29" fill="#e77459"/><circle cx="112" cy="66" r="4" fill="#173e35"/><circle cx="113" cy="65" r="1" fill="white"/><path d="M105 54q8-5 15 1" fill="none" stroke="#6d6340" stroke-width="3" stroke-linecap="round"/><path class="wing" d="M58 109q26-24 37 6q-10 37-37-6" fill="#67a18a"/><path d="M83 97l12 10 10-11" fill="white"/><path d="M95 105l-4 17 6 6 5-7-6-16" fill="#234e43"/><path d="M74 154v12m27-12v12m-27 0h-11m11 0h10m17 0h-9m9 0h12" stroke="#d4a33c" stroke-width="5" stroke-linecap="round"/></g></svg></button>`}
function save(){
 state.active=active;
 try{
  storageOK=persistProgress(localStorage,state);
 }catch{storageOK=false;syncText='Local saving unavailable — export a backup'}
 if(derivedEvents!==state.events||derivedCount!==state.events.length){P=derive(state.events);derivedEvents=state.events;derivedCount=state.events.length}
 header();
}

function add(kind,payload){state.events.push(event(kind,payload));save()}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.add('hidden'),5000)}
function header(){
 const status=storageOK?'Saved on this device':'Saving unavailable — export backup';
 const tone=storageOK?'online':'error';
 document.getElementById('topstats').innerHTML=`${button('nav',`<span class="status-dot ${tone}"></span><span class="sync-label">${esc(status)}</span>`,'save-status',`data-view="progress" aria-label="${esc(status)}. Open saving settings"`)}<span class="pill xp">✦ ${P.xp.toLocaleString()} XP</span><span class="pill days">☀ ${consecutiveDays(P.days,dayKey())} day streak</span>`;
 document.getElementById('nav').innerHTML=[['home','⌂','My path'],['subjects','▦','Subjects'],['review','↻','Review'],['mock','◷','Exam room'],['sources','▤','Sources'],['progress','♧','My progress']].map(([id,icon,label])=>button('nav',`<span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span>`,view===id?'active':'',`data-view="${id}" ${view===id?'aria-current="page"':''}`)).join('');
}

function navigate(to){
 if(!['home','subjects','review','mock','sources','progress','session','result','library','guide'].includes(to))to='home';
 if(to!=='session'&&'speechSynthesis'in window)speechSynthesis.cancel();
 view=to;render();if(location.protocol!=='file:'&&location.hash!=='#'+to)history.pushState(null,'',location.pathname+location.search+'#'+to);
 window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});
}

function render(){
 document.body.classList.toggle('focus-mode',view==='session');
 document.body.classList.toggle('large-text',!!state.settings.largeText);
 document.body.classList.toggle('reduce-motion',!!state.settings.reduceMotion);
 header();({home,subjects,review,mock:mockPage,sources,progress,session,result,library,guide:subjectGuide}[view]||home)();
 if(view==='home'){const hero=main.querySelector('.hero');hero?.insertAdjacentHTML('afterend',`<div class="quick-actions">${button('bonus','🥚 Legalu’s daily quest · 2× XP','bonus-button')}${button('quick','⚡ Ten-question warm-up','', 'aria-label="Start ten mixed recall questions"')}${button('nav','⌕ Find a book question','ghost','data-view="library"')}</div>`)}
}

function nextLesson(){return B.lessons.find(l=>!P.lessons.has(l.id))}
function home(){const n=nextLesson(),today=P.days[dayKey()]||{attempts:0,correct:0},seen=BOOK.filter(q=>s(q.id).seen).length,retained=BOOK.filter(q=>s(q.id).level>=3).length;const ls=B.lessons.filter(l=>l.day===chosenDay),daily=ls.reduce((a,l)=>a+l.questions.length,0);main.innerHTML=`
 <section class="hero"><div><div class="eyebrow">14—17 OCTOBER · YOUR LAW-GAT SPRINT</div><h1>One question closer.<br>Every single day.</h1><p>You don’t have to hold the whole syllabus in your head. Let’s learn a little, recall it, and come back to it.</p></div><div class="hero-art">${mascot()}</div></section>
 <div class="dashboard"><div><section class="card mission"><div class="eyebrow">${active?'PICK UP WHERE YOU LEFT OFF':'YOUR NEXT SMALL WIN'}</div><h2>${active?esc(active.title):n?esc(n.title):'You’ve walked the whole path.'}</h2><p class="muted">${active?(active.mode==='mock'?'Your answers are saved. The exam timer keeps running during breaks.':'Your question and selected answer are saved. Continue whenever you’re ready.'):n?`${n.questions.length} book questions · explanations + memory cues · pause whenever you need`:'Keep your recall fresh with your due reviews.'}</p>${button(active?'resume':n?'lesson':'due',active?'Continue session →':n?'Start this lesson →':'Refresh my memory →','gold',n?`data-id="${n.id}"`:'')}</section>
 <div class="row between"><h2 style="margin:0">Your book-learning path</h2><span class="badge">${P.lessons.size} / ${B.lessons.length} lessons</span></div><div class="tabs" role="group" aria-label="Study day">${[1,2,3,4].map(d=>button('day',`<strong>Day ${d}</strong><br><small style="color:inherit">${13+d} Oct</small>`,chosenDay===d?'active':'',`data-day="${d}"`)).join('')}</div><p class="source-note">${daily} book questions today. Work in short sittings; add 15–20 minutes for recall. ${chosenDay===4?'Use the short mock when time is tight; reserve an extra block for a full mock.':'Covering the full book can take longer than 2–3 hours. Keep moving steadily, and revisit mistakes.'}</p><div class="path">${ls.map(l=>`<div class="lesson"><button data-action="lesson" data-id="${l.id}" class="lesson-node ${P.lessons.has(l.id)?'done':n?.id===l.id?'next':''}" aria-label="${esc(l.title)}">${P.lessons.has(l.id)?'✓':l.order}</button><div class="lesson-copy"><strong>${esc(l.title)}</strong><small>Book Q${l.range} · ${l.questions.length} questions${P.lessons.has(l.id)?' · completed':''}</small></div>${n?.id===l.id?'<span class="badge">NEXT</span>':''}</div>`).join('')}</div></div>
 <div class="sidebar-cards"><section class="card"><div class="row between"><h3 style="margin:0">Your memory garden</h3><span>🌱</span></div><div class="numbers"><div><strong>${seen}</strong><small>met so far</small></div><div><strong>${retained}</strong><small>recalled later</small></div><div><strong>${BOOK.length}</strong><small>in your book</small></div></div><div class="meter"><span style="width:${percent(seen,BOOK.length)}%"></span></div><p class="source-note">A question becomes “recalled later” after successful spaced reviews. Getting it right once is a beginning.</p></section>
 <section class="card"><div class="eyebrow">TODAY’S MOMENTUM</div><h2 style="margin:10px 0">${today.attempts} questions practised</h2><p class="muted">${today.attempts?`${percent(today.correct,today.attempts)}% correct today. Every mistake gives us something useful to revisit.`:'Start with one lesson. You can pause and return at any time.'}</p><div class="meter"><span style="width:${Math.min(100,today.attempts/150*100)}%"></span></div><small>Flexible goal: 150 attempts</small></section>
 <section class="card"><h3>Keep yesterday’s learning</h3><p class="muted">${due().length} due for recall · ${weak().length} in your repair pile.</p>${button('due','↻ Start a quick review','','style="width:100%"')}</section>${P.legacy?`<section class="card"><h3>Your earlier work counts</h3><p class="muted">${P.legacy.lessons.length} original lessons imported, with ${P.legacy.xp} XP. The book path tracks the new questions separately.</p></section>`:''}</div></div>`}
function subjects(){main.innerHTML=`<div class="eyebrow">THE WHOLE SYLLABUS, ONE SUBJECT AT A TIME</div><h1 style="margin-top:10px">Build your foundations.</h1><p class="muted">Choose book MCQs for exam wording, or foundation drills when a rule needs a simpler explanation.</p><div class="subject-grid">${Object.entries(B.subjects).map(([id,o])=>{const qs=BOOK.filter(q=>q.subject===id),seen=qs.filter(q=>s(q.id).seen).length;return `<section class="card"><div class="subject-top"><span class="subject-glyph">${o.glyph}</span><span class="badge">${o.weight}% OF SYLLABUS</span></div><h2>${o.name}</h2><p class="muted">${seen} / ${qs.length} book MCQs practised</p><div class="meter"><span style="width:${percent(seen,qs.length)}%"></span></div><div class="row">${button('subject','Book practice','primary',`data-id="${id}"`)}${button('foundation','Explain simply','',`data-id="${id}"`)}${button('guide','Read subject guide','ghost',`data-id="${id}"`)}</div></section>`}).join('')}</div>`}
function review(){const d=due(),w=weak(),history=[...Q.values()].filter(q=>s(q.id).wrong);main.innerHTML=`<div class="hero"><div><div class="eyebrow">MISTAKES ARE YOUR STUDY GUIDE</div><h1>Let’s make it stick.</h1><p>Missed and guessed answers return sooner. Correct answers return after a longer gap.</p></div><div class="hero-art">${mascot('thoughtful')}</div></div><div class="split"><section class="card"><h2>Due for a refresh</h2><p class="muted">${d.length} questions are ready for another recall.</p>${button('due','Review up to 20','primary')}</section><section class="card"><h2>Your repair pile</h2><p class="muted">${w.length} weak or bookmarked questions. No lost hearts. No punishment.</p>${button('weak','Work on mistakes','gold')}</section></div><section class="card"><h2>Questions you’ve stumbled on</h2>${history.length?history.slice().sort((a,b)=>s(b.id).wrong-s(a.id).wrong).map(q=>`<div class="review-item"><div class="row between"><span class="badge">${esc(q.subject)}${q.number?' Q'+q.number:''}</span><small>${s(q.id).wrong} missed · ${s(q.id).level>=2?'recovering well':'needs another look'}</small></div><p style="margin:10px 0">${esc(q.question)}</p>${button('single','Practise this','','data-id="'+q.id+'"')}</div>`).join(''):'<p class="muted">Your missed answers will appear here automatically.</p>'}</section>`}
function sources(){const counts={};BOOK.forEach(q=>counts[q.status]=(counts[q.status]||0)+1);main.innerHTML=`<div class="eyebrow">KNOW WHAT YOU’RE PRACTISING</div><h1 style="margin-top:10px">The source matters.</h1><section class="card"><h2>Your “600 Important MCQs” book</h2><p>${BOOK.length} numbered questions have been transcribed from your PDF. Some long stems are cleaned or condensed for phone reading. Every book question links to its original scanned page.</p><p><strong>This is a private preparation book, not an authenticated HEC past paper.</strong> The printed key is preserved alongside corrections where needed.</p><div class="row">${Object.entries(counts).map(([status,n])=>`<span class="badge ${status==='verified'?'verified':'warn'}">${n} ${esc(status)}</span>`).join('')}</div><div class="callout">Historical, disputed and unverified items remain available for study with a warning. Scored book mocks require a verified answer, four distinct options and a match to the listed HEC syllabus scope. Extra book questions remain in the lessons.</div></section><section class="card"><h2>Official HEC sample</h2><p>50 original sample-paper questions, with answers checked against HEC’s marked key. The original wording is shown as an image with answer colour removed. Older constitutional questions need edition awareness.</p>${button('sample','Practise the official sample','primary')} <a href="https://www.hec.gov.pk/english/services/students/etc/Documents/LAW%20GAT%20Sample%20Paper.pdf" target="_blank" rel="noopener">Read HEC’s PDF</a></section><section class="card"><h2>Law and syllabus references</h2><p class="muted">Book explanations cite provisions or primary sources. An official PDF may itself be an older consolidation; relevant later amendments are called out.</p><div class="stack">${Object.entries(B.sources).map(([id,o])=>o.url?`<a href="${esc(o.url)}" target="_blank" rel="noopener">${esc(o.label||id)}</a>`:'').join('')}<a href="https://pakistancode.gov.pk/pdffiles/administratord5622ea3f15bfa00b17d2cf7770a8434.pdf" target="_blank" rel="noopener">Updated PPC consolidation</a><a href="https://www.na.gov.pk/uploads/documents/64f83bdd72ead_978.pdf" target="_blank" rel="noopener">2022 repeal of PPC section 325</a></div></section><section class="card"><h2>What the labels mean</h2><p><strong>Verified:</strong> checked against the cited legal source. <strong>Historical:</strong> older law or a superseded answer. <strong>Disputed:</strong> ambiguous stem, faulty options, or conflicting key. <strong>Unverified:</strong> not sufficiently resolved for scoring.</p><p>Foundation drills are authored explanations and scenarios. Practice mocks are generated from the verified question bank; they are not claimed to be past papers. These materials support study and cannot guarantee a score.</p></section>`}
function progress(){
 main.innerHTML=`<div class="eyebrow">YOUR PROGRESS, ON THIS DEVICE</div><h1 style="margin-top:10px">Your progress, saved.</h1><div class="split"><section class="card"><h2>Automatic saving</h2><p class="muted">Answers, mistakes, XP and your place in a lesson save automatically in this browser. Use the same site address and browser each day. To move between laptop and phone, export here and import on the other device.</p><p class="source-note">Last successful save: ${state.savedAt?esc(new Date(state.savedAt).toLocaleString()):'not yet recorded'}. An automatic recovery copy is kept in this browser when space allows. Exported backups also protect against clearing browser data.</p><span class="badge ${storageOK?'verified':'warn'}">${storageOK?'LOCAL SAVING ACTIVE':'EXPORT A BACKUP NOW'}</span><p class="source-note" style="margin-top:15px">No account is needed. Export before clearing browser data or moving to a different browser.</p></section><section class="card"><h2>Your backup</h2><p class="muted">Save a backup after each study session. Imports merge your work without duplicating the same answers.</p><div class="row">${button('export','Export my progress','primary')}<label for="import" class="file-label">Import a backup<input type="file" id="import" accept="application/json,.json"></label></div></section></div><section class="card"><h2>Make it comfortable</h2><div class="settings-options"><label><input id="sound" type="checkbox" ${state.settings.sound?'checked':''}> A soft chime for a correct answer</label><label><input id="largeText" type="checkbox" ${state.settings.largeText?'checked':''}> Larger question text</label><label><input id="reduceMotion" type="checkbox" ${state.settings.reduceMotion?'checked':''}> Less animation</label></div><p class="source-note">Keyboard: 1–4 chooses an answer. Enter checks it or continues. You can also use the mouse throughout.</p></section><section class="card"><h2>Your study record</h2><div class="numbers"><div><strong>${P.xp}</strong><small>total XP</small></div><div><strong>${P.lessons.size}</strong><small>book lessons</small></div><div><strong>${P.mocks.length}</strong><small>mock attempts</small></div></div>${P.legacy?`<p class="muted">Preserved from your earlier app: ${P.legacy.lessons.length} lessons, ${P.legacy.seq||0} attempts and ${P.legacy.xp} XP.</p>`:''}</section>`;
}
function mockPage(){main.innerHTML=`<div class="hero"><div><div class="eyebrow">14–17 OCTOBER · EXAM PRACTICE</div><h1>Four papers. A clearer picture.</h1><p>100 questions in each paper, four options and one best answer. Answers stay hidden until submission.</p></div><div class="hero-art">${mascot()}</div></div>${syllabusPanel()}<section class="card"><h2>Choose your rehearsal</h2><p>Each paper follows the HEC syllabus weighting: CPC 20, Evidence 20, Constitution 10, Ethics 10, PPC 10, CrPC 10, and 5 each for Cases, International, English and Islamic Jurisprudence.</p><p class="source-note">These are practice papers assembled from verified book questions, not official past papers. Selection cycles through syllabus topics within each subject, then favours less-used questions. These topic allocations are teaching choices, not official HEC subtopic quotas. Small subject pools repeat some questions across papers. Original book option order is retained.</p><label for="duration">Full-paper practice timer</label><select id="duration" class="input"><option value="120">120 minutes</option><option value="100">100 minutes</option><option value="150">150 minutes</option></select><p class="source-note">Use the timing on your admission slip. This is a practice setting. One mark per correct answer; no negative marking in this app.</p></section><div class="subject-grid">${B.papers.map((paper,i)=>{const attempts=P.mocks.filter(m=>m.paperId===paper.id);return `<section class="card"><span class="badge">PAPER ${i+1} · 100 MCQs</span><h2>${esc(paper.title)}</h2><p class="muted">${attempts.length?`${attempts.length} attempt(s) · best ${Math.max(...attempts.map(m=>m.score))}/100`:'Not attempted yet. A fixed paper, so you can compare your later retake.'}</p>${button('paper',attempts.length?'Retake paper →':'Start paper →','primary',`data-id="${paper.id}"`)}</section>`}).join('')}</div><section class="card"><h2>Shorter practice and original questions</h2><p class="muted">A short mock takes 25 minutes. The official sample uses the original 50 HEC questions with feedback after each answer.</p><div class="row">${button('shortmock','20-question mixed mock','gold')}${button('startmock','Fresh random 100-question mock')}${button('sample','Official HEC sample')}${button('sampletimed','Timed official sample · 60 min')}</div><p class="source-note">You do not need to finish all four full papers in four days. Learn and repair first; use the short mock on busy days and a full rehearsal when you have a separate time block.</p></section><section class="card"><h2>Past attempts — reopen and repair</h2>${P.mocks.length?P.mocks.slice().reverse().map(m=>`<div class="review-item row between"><div><strong>${esc(m.title)}</strong><p class="muted">${m.score}/${m.total} · ${new Date(m.at).toLocaleString()}</p></div>${button('mockresult','Review answers','','data-id="'+m.id+'"')}</div>`).join(''):'<p class="muted">Every submitted mock will be saved here with its answers and mistakes.</p>'}</section>`}
let guideSubject='CPC';
function subjectGuide(){const subject=B.subjects[guideSubject],qs=B.questions.filter(q=>q.subject===guideSubject&&q.sourceType==='foundation');main.innerHTML=`<div class="eyebrow">UNDERSTAND → RECALL → APPLY</div><h1>${esc(subject.name)}: the study guide</h1><p class="muted">A plain-language companion to the book. Read a small group, explain the rule aloud, then answer without peeking. These authored teaching notes supplement the source-labelled book lessons.</p><div class="row">${button('nav','← Subjects','','data-view="subjects"')}${button('foundation','Practise these ideas','primary','data-id="'+guideSubject+'"')}${active?button('resume','Return to saved lesson'):''}</div><section class="card"><h2>A useful way to study this subject</h2><ol><li>Name the rule and its provision or source.</li><li>Say what fact triggers it, and what changes if an exception applies.</li><li>Close the explanation. Answer aloud before opening the recall card.</li><li>Practise the book questions; mark guesses so they return.</li></ol></section>${qs.map((q,i)=>`<section class="card"><span class="badge">CONCEPT ${i+1}</span><h2>${esc(q.topic||q.reference)}</h2><p>${esc(q.explanation)}</p>${memoryHTML(q)}<details class="review-item"><summary>Recall: ${esc(q.question)}</summary><p><strong>${esc(q.options[q.answer])}</strong></p><p>${esc(q.reference)}</p></details>${q.scenario?`<details class="review-item"><summary>Apply: ${esc(q.scenario)}</summary><p><strong>${esc(q.options[q.answer])}</strong></p><p>${esc(q.explanation)}</p></details>`:''}${button('single','Try as an MCQ','','data-id="'+q.id+'"')}${source(q)}</section>`).join('')}`}
async function startPaper(id){const paper=B.papers.find(p=>p.id===id);if(!paper)return;const minutes=Number(document.getElementById('duration')?.value||120);if(await begin(paper.ids,paper.title,'mock',null,minutes)){active.paperId=id;save()}}
function subjectBreakdown(items){if(items.every(i=>Q.get(i.qid)?.subject==='HEC'))return '<section class="card"><h2>Official sample review</h2><p>Open each answer below to see the original question image and explanation. Historical questions retain the sample key; read the edition notes before treating a rule as current.</p></section>';return `<section class="card"><h2>Where to spend your next study block</h2><p class="muted">Repair missed and unanswered questions, then return after a break. Retaking immediately measures short-term recall.</p><div class="subject-grid">${Object.entries(B.subjects).map(([id,o])=>{const rows=items.filter(i=>Q.get(i.qid)?.subject===id);if(!rows.length)return '';const correct=rows.filter(i=>i.choice===(i.answer??Q.get(i.qid)?.answer)).length,blank=rows.filter(i=>i.choice===undefined).length;return `<div class="mini-rule"><strong>${esc(o.name)}</strong><p>${correct}/${rows.length} correct · ${blank} unanswered</p><div class="meter"><span style="width:${percent(correct,rows.length)}%"></span></div>${correct<rows.length?button('repairsubject','Repair this subject','','data-id="'+id+'"'):'<small>All correct in this attempt.</small>'}</div>`}).join('')}</div></section>`}

async function confirmAction(message,label='Continue'){
 if(cancelModal)return false;
 return new Promise(resolve=>{
  const previous=document.activeElement,overlay=document.createElement('div');let closed=false;
  overlay.className='modal-backdrop';overlay.innerHTML=`<section class="card" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><h2 id="confirm-title">${esc(label)}</h2><p>${esc(message)}</p><div class="row"><button type="button">Keep working</button><button type="button" class="primary">${esc(label)}</button></div></section>`;
  document.body.append(overlay);const bs=overlay.querySelectorAll('button');
  function close(value){if(closed)return;closed=true;cancelModal=null;overlay.remove();previous?.focus();resolve(value)}
  cancelModal=()=>close(false);bs[0].onclick=()=>close(false);bs[1].onclick=()=>close(true);
  overlay.onkeydown=e=>{if(e.key==='Escape')close(false);if(e.key==='Tab'){e.preventDefault();bs[document.activeElement===bs[0]?1:0].focus()}};bs[0].focus();
 });
}
async function begin(ids,title,mode='practice',lessonId=null,minutes=0){
 if(!ids.length){toast('Nothing due yet. Try a subject lesson, or come back after a break.');return false}
 if(active&&lessonId&&active.lessonId===lessonId){navigate('session');return true}
 if(active&&!await confirmAction('Starting this session replaces the unfinished one. All answers you already recorded stay saved.','Start new session'))return false;
 active={ids:[...ids],title,mode,lessonId,index:0,phase:lessonId?'intro':'question',choices:{},priorSeen:Object.fromEntries(ids.map(id=>[id,!!s(id).seen])),answers:[],repair:[],repaired:[],choice:null,guessed:false,started:Date.now(),deadline:minutes?Date.now()+minutes*60000:null,finished:false};
 if(Q.get(ids[0])?.sourceType==='foundation'){active.optionOrder=shuffle([0,1,2,3]);active.variant=Math.random()<.5}
 save();navigate('session');return true;
}
function beginLesson(id){const l=B.lessons.find(l=>l.id===id);if(l)begin(l.questions,l.title,'lesson',id)}
function qAt(){return Q.get(active?.ids[active.index])}
for(const entry of sampleEntries()){
 const d=B.sampleDetails[entry.number-1];
 Q.set(`sample-${entry.number}`,{id:`sample-${entry.number}`,subject:'HEC',question:`Official HEC sample · Question ${entry.number}`,options:['A','B','C','D'],answer:entry.answer,number:entry.number,sourceType:'sample',status:'historical',explanation:d[3],reference:d[2],cue:'Read all four alternatives. Recall the rule before choosing.'});
}

function sampleEntries(){const raw=B.sample;return Array.isArray(raw)?raw.map((x,i)=>typeof x==='object'?{number:x.number||x.q||i+1,answer:typeof x.answer==='number'?x.answer:'ABCD'.indexOf(x.answer||x.key)}:{number:i+1,answer:typeof x==='number'?x:'ABCD'.indexOf(x)}):Object.entries(raw).map(([n,a])=>({number:+n,answer:typeof a==='object'?(typeof a.answer==='number'?a.answer:'ABCD'.indexOf(a.answer)):typeof a==='number'?a:'ABCD'.indexOf(a)}))}
function source(q){const page=q.page?`book-pages/${String(q.page).padStart(2,'0')}.png`:null;return `<details class="source-note"><summary>Source and answer notes</summary><p>${esc(sourceLabel(q))}${q.wording==='condensed'?' · stem condensed for readability':''}<br>${esc(q.reference)}</p>${page?`<a href="${page}" target="_blank" rel="noopener">See the original book page ↗</a>`:''}${q.sourceType==='book'&&q.bookAnswer!==null&&q.bookAnswer!==undefined?`<p>Printed book key: ${String.fromCharCode(65+q.bookAnswer)}${q.bookAnswer!==q.answer?' · differs from the checked answer':''}.</p>`:''}</details>`}
function session(){if(!active){navigate('home');return}const q=qAt();if(!q){toast('This saved question is unavailable in this edition. Your recorded progress is safe.');active=null;save();navigate('home');return}if(active.phase==='intro'){const l=B.lessons.find(l=>l.id===active.lessonId),rules=l.questions.map(id=>Q.get(id)).filter(x=>x.status==='verified').filter((x,i,a)=>a.findIndex(y=>y.explanation===x.explanation)===i);main.innerHTML=`<div class="quiz"><div class="row between">${button('pause','← My path','ghost')}<span class="badge">LESSON ${l.order}</span></div><section class="card"><div class="row between"><div><div class="eyebrow">FIRST, MAKE THE IDEA SIMPLE</div><h1 style="font-size:32px;margin:10px 0">${esc(l.title)}</h1><span class="badge">YOUR BOOK · Q${l.range}</span></div>${mascot()}</div><p class="muted">${l.questions.length} questions from your book. Answer first, then read why. Any shaky answers get another turn at the end.</p>${button('startquestions','Start MCQs now →','primary')}<h2>The rules in this lesson</h2><p class="muted">Read a few at a time. You can return to these notes whenever you repeat the lesson.</p>${!rules.length?'<p class="notice">This unit has no fully verified book rules to preview. Read its source notes carefully; uncertain questions are excluded from scored mocks. The subject guide provides separately labelled foundation explanations.</p>':''}<div class="lesson-intro">${rules.map(r=>`<div class="mini-rule"><strong>${esc(r.reference)}</strong><p>${esc(r.explanation)}</p>${memoryHTML(r)}</div>`).join('')}</div><p class="source-note">These rules come from the exact book questions in this lesson. Read them once, then try to recall them without looking. Every question has its own explanation and original-page link.</p><h2>Recall before choosing</h2><p class="muted">Say the answer in your own words, then open the card. These are warm-up cards; your scored attempts begin below.</p>${rules.map(r=>`<details class="review-item"><summary>${esc(r.question)}</summary><p><strong>${esc(r.options[r.answer])}</strong></p><p>${esc(r.explanation)}</p>${memoryHTML(r)}</details>`).join('')}<div class="row">${button('startquestions','Ready — ask me →','primary')}${button('guide','Open subject guide','','data-id="'+l.subject+'"')}</div></section></div>`;return}
const isMock=active.mode==='mock',feedback=active.phase==='feedback',answered=active.answers.length,warning=['disputed','unverified','historical'].includes(q.status)&&q.sourceType==='book';main.innerHTML=`<div class="quiz"><div class="quiz-head">${button('pause','← Save & leave','ghost','aria-label="Save and leave this session"')}<div class="meter big" role="progressbar" aria-label="Question progress" aria-valuenow="${active.index}" aria-valuemin="0" aria-valuemax="${active.ids.length}"><span style="width:${percent(active.index,active.ids.length)}%"></span></div><strong class="question-count">${active.index+1} / ${active.ids.length}</strong>${isMock?'<span class="pill timer" id="timer" title="Exam time continues during breaks"></span>':''}</div><div class="row between"><span class="eyebrow">${esc(active.title)}</span>${q.sourceType==='book'?`<span class="badge ${graded(q)?'verified':'warn'}">${esc(q.status)}</span>`:'<span class="badge">'+(q.sourceType==='sample'?'OFFICIAL SAMPLE':'FOUNDATION')+'</span>'}</div><section class="card question-card"><div class="row between"><span class="source-note">${esc(q.sourceType==='sample'?`HEC sample Q${q.number}`:sourceLabel(q))}</span>${!isMock?button('bookmark',P.bookmarks.has(q.id)?'★ Saved':'☆ Save','ghost','aria-label="Bookmark question"'):''}</div>${q.sourceType==='sample'?`<h2 class="question">${esc(q.question)}</h2><img loading="lazy" decoding="async" class="question-img" src="sample-questions/${String(q.number).padStart(2,'0')}.png" alt="Original question ${q.number} from HEC sample paper. Options are printed in the image.">`:`<h2 class="question">${esc(q.scenario&&active.variant?q.scenario:q.question)}</h2>`}${warning?`<div class="notice">${q.status==='historical'?'Historical or superseded law: this item is for edition awareness.':'This book item needs caution. Read the explanation; it does not count as scored mastery.'}</div>`:''}${active.hint&&!feedback&&!isMock?`<div class="lesson-intro"><strong>Look for the rule in:</strong> ${esc(q.reference)}<p class="source-note" style="margin:6px 0 0">This goes into your repeat practice, so you can recall it without the hint later.</p></div>`:''}<div class="answers">${(active.optionOrder||q.options.map((_,i)=>i)).map((original,position)=>{let cls='';if(feedback){if(original===q.answer)cls='correct';else if(original===active.choice)cls='incorrect'}else if(original===(isMock?active.choices[q.id]:active.choice))cls='selected';return button('choice',`<span class="letter">${String.fromCharCode(65+position)}</span><span>${esc(q.options[original])}${feedback&&original===q.answer?'<span class="answer-verdict">✓ '+(canAnswer(q)?'Correct answer':'Working answer')+'</span>':feedback&&original===active.choice?'<span class="answer-verdict">✕ Your answer</span>':''}</span>`,'answer '+cls,`data-choice="${original}" ${feedback?'disabled':''} aria-pressed="${original===(isMock?active.choices[q.id]:active.choice)}"`)}).join('')}</div>
${feedback?feedbackHTML(q):''}</section><div class="quiz-footer"><div class="row">${isMock?`${button('previous','← Previous','',active.index===0?'disabled':'')}${button('mocknext',active.index===active.ids.length-1?'Review & submit':'Next →','primary')}`:feedback?`${button('readaloud','Hear the explanation','ghost')}${button('next','Continue →','primary')}`:`${q.sourceType==='book'&&!active.hint?button('hint','Need a small hint?','ghost'):''}<label><input type="checkbox" id="guessed" ${active.guessed?'checked':''} ${active.hint?'disabled':''}> I’m guessing</label>${button('check',!canAnswer(q)&&q.sourceType!=='sample'?'Show explanation':'Check answer','primary',active.choice===null&&canAnswer(q)?'disabled':'')}`}</div></div>${isMock?`<section class="card"><div class="row between"><h3>Question navigator</h3><p class="source-note">The exam timer continues if you leave or close the app. Lessons have no timer.</p>${button('submitmock','Submit mock','ghost')}</div><div class="mock-map">${active.ids.map((id,i)=>button('jump',i+1,active.choices[id]!==undefined?'answered':'',`data-index="${i}" aria-label="Question ${i+1}${active.choices[id]!==undefined?', answered':''}"`)).join('')}</div></section>`:''}</div>`;if(isMock)updateTimer()}
function feedbackHTML(q){const scorable=canAnswer(q)||q.sourceType==='sample',correct=active.choice===q.answer;return `<div class="feedback ${correct?'':'wrong'}" role="status" aria-live="polite"><div class="row between"><h3>${!scorable?'Let’s unpack this one.':correct?(active.guessed?'Right — now let’s make it certain.':'Yes! That’s the one.'):'A useful mistake. Let’s fix it.'}</h3><div style="width:75px;height:75px">${mascot(correct?'happy':'thoughtful')}</div></div>${q.answer!==null?`<p><strong>${q.sourceType==='sample'?'HEC marked answer':q.status==='unverified'?'Working answer — not verified':q.status==='historical'?'Historical answer':'Answer'}: ${esc(q.options[q.answer])}</strong></p>`:'<p><strong>No dependable single answer in these options.</strong></p>'}<p>${esc(q.explanation)}</p>${memoryHTML(q)}${source(q)}${scorable?`<div class="reward-line">+${active.lastReward||0} XP ${active.bonus?'· Bonus quest':''}${active.answerStreak>=3?' · '+active.answerStreak+' correct in a row 🔥':''}</div>`:''}${!correct&&scorable?'<small>You’ll meet this again. You don’t need to memorise it in one go.</small>':''}</div>`}
function check(){
 if(!active||active.phase!=='question')return;
 const q=qAt(),scorable=canAnswer(q)||q.sourceType==='sample';if(active.choice===null&&scorable)return;
 active.phase='feedback';const correct=active.choice===q.answer;
 if(scorable){
  const eligible=!s(q.id).last||Date.now()>=s(q.id).due;const xp=rewardXP({correct,guessed:active.guessed,eligible,bonus:!!active.bonus});active.lastReward=xp;active.answerStreak=correct&&!active.guessed?(active.answerStreak||0)+1:0;
  active.answers.push({qid:q.id,correct,choice:active.choice,guessed:active.guessed});
  if((!correct||active.guessed)&&!active.repaired.includes(q.id)&&!active.repair.includes(q.id))active.repair.push(q.id);
  add('answer',{qid:q.id,choice:active.choice,correct,guessed:active.guessed,mode:active.mode,xp,bonus:!!active.bonus});
  if(correct&&!active.guessed){celebrate();chime()}
 }else add('answer',{qid:q.id,choice:active.choice,correct:false,ungraded:true,mode:active.mode,xp:0});
 session();const feedback=main.querySelector('.feedback');feedback?.setAttribute('tabindex','-1');feedback?.focus({preventScroll:true});feedback?.scrollIntoView({block:'nearest',behavior:state.settings.reduceMotion?'instant':'smooth'});
}

function advance(){if(!active)return;active.index++;active.choice=null;active.guessed=false;active.hint=false;active.optionOrder=null;active.phase='question';if(active.index>=active.ids.length){if(active.repair.length){const ids=shuffle(active.repair);active.ids.push(...ids);active.repaired.push(...ids);active.repair=[];toast('A short repair round: let’s try the shaky ones again.')}else{complete();return}}if(active.mode==='practice'&&qAt()?.sourceType==='foundation'){active.optionOrder=shuffle([0,1,2,3]);active.variant=Math.random()<.5}save();session();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function complete(){const a=active;summary={title:a.title,score:a.answers.filter(x=>x.correct).length,total:a.answers.length,unique:new Set(a.ids).size,mode:a.mode,repairs:a.repaired.length};if(a.bonus){state.settings.bonusCompletedDay=dayKey()}if(a.lessonId)add('lesson',{id:a.lessonId});active=null;save();navigate('result')}
function result(){if(!summary){navigate('home');return}main.innerHTML=`<section class="card empty"><div>${mascot('happy')}</div><div class="eyebrow">ANOTHER STEP FORWARD</div><h1 style="margin-top:15px">${summary.mode==='mock'?'Your rehearsal is complete.':'You showed up. That matters.'}</h1><p class="muted">${esc(summary.title)}</p><div class="score-ring"><strong>${summary.total?summary.score:'✓'}</strong><small>${summary.total?'of '+summary.total:'Reference review'} ${summary.mode==='mock'?'marks':'attempts correct'}</small></div><p>${summary.mode==='mock'?'Review the explanations below. Unanswered questions score zero.':`${summary.unique} different questions visited${summary.repairs?`, including ${summary.repairs} repair questions`:''}. Come back after a gap to strengthen recall.`}</p>${summary.items?readinessNote(summary.items):''}<div class="row" style="justify-content:center">${button('nav','Back to my path','primary','data-view="home"')}${summary.items?button('mockmistakes','Practise missed questions'):button('nextlesson','Continue my path')}</div></section>${summary.items?`${subjectBreakdown(summary.items)}<section class="card"><h2>Your answer review</h2>${summary.items.map(item=>{const q=Q.get(item.qid);if(!q)return '';return `<details class="review-item"><summary>${item.choice===(item.answer??q.answer)?'✓':item.choice===undefined?'—':'✕'} ${esc(q.subject)} · ${esc(q.question)}</summary>${q.sourceType==='sample'?`<img loading="lazy" decoding="async" class="question-img" src="sample-questions/${String(q.number).padStart(2,'0')}.png" alt="Original HEC sample question ${q.number}">`:''}<p style="margin-top:14px">Your answer: ${item.choice===undefined?'Unanswered':esc(q.options[item.choice])}<br><strong>Correct: ${esc(q.options[item.answer??q.answer])}</strong></p><p>${esc(q.explanation)}</p>${memoryHTML(q)}${source(q)}</details>`}).join('')}</section>`:''}`;celebrate()}
function startMock(n){const ids=[];for(const [subject,o]of Object.entries(B.subjects)){const take=n===100?o.weight:o.weight/5;const pool=BOOK.filter(q=>q.subject===subject&&mockEligible(q));if(pool.length<take){toast(`Not enough verified ${subject} questions for this mock.`);return}ids.push(...selectBlueprint(pool,take,Math.floor(Math.random()*100),Object.fromEntries(pool.map(q=>[q.id,Math.random()]))))}const minutes=n===100?Number(document.getElementById('duration')?.value||120):25;begin(shuffle(ids),`${n}-question syllabus mock`,'mock',null,minutes)}
async function submitMock(timeout=false){
 if(!active||active.mode!=='mock'||active.finished)return;
 const attempt=active,count=Object.keys(attempt.choices).length;
 if(timeout)cancelModal?.();
 if(!timeout&&!await confirmAction(`${count} of ${attempt.ids.length} answered. Submit now? Unanswered questions score zero.`,'Submit mock'))return;
 if(active!==attempt||attempt.finished)return;
 attempt.finished=true;
 const items=attempt.ids.map(qid=>({qid,choice:attempt.choices[qid],answer:Q.get(qid).answer,priorSeen:attempt.priorSeen?.[qid]}));
 const score=items.filter(i=>i.choice===i.answer).length,title=attempt.title;
 for(const i of items)state.events.push(event('answer',{qid:i.qid,choice:i.choice,correct:i.choice===i.answer,guessed:false,mode:'mock',...(i.choice===undefined?{skipped:true,xp:0}:{})}));
 summary={title,score,total:items.length,mode:'mock',items,paperId:attempt.paperId||null};add('mock',{title,score,total:items.length,items,paperId:attempt.paperId||null});
 active=null;save();navigate('result');if(timeout)toast('Time is up. Your mock was submitted automatically.');
}

function updateTimer(){if(!active?.deadline||active.mode!=='mock')return;const seconds=Math.max(0,Math.ceil((active.deadline-Date.now())/1000)),el=document.getElementById('timer');if(el)el.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;if(seconds===0)submitMock(true)}
function celebrate(){if(state.settings.reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const root=document.getElementById('celebration');for(let i=0;i<16;i++){const e=document.createElement('i');e.className='confetti';e.style.cssText=`--dx:${Math.random()*450-225}px;--dy:${Math.random()*350-100}px;--spin:${Math.random()*600}deg;background:${['#f3bf4b','#79ac87','#ed8b6c'][i%3]};`;root.append(e);setTimeout(()=>e.remove(),1000)}}
function chime(){if(!state.settings?.sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();[523,659].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=f;g.gain.setValueAtTime(.045,ctx.currentTime+i*.09);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.25+i*.09);o.connect(g).connect(ctx.destination);o.start(ctx.currentTime+i*.09);o.stop(ctx.currentTime+.3+i*.09)});setTimeout(()=>ctx.close(),800)}catch{}}
function exportProgress(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`lawlingo-progress-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded. Keep it somewhere you can find again.')}
async function importProgress(file){try{if(file.size>30000000)throw Error('This file is too large to be a progress backup.');const parsed=JSON.parse(await file.text());if(validate(parsed)){state.events=merge(state.events,parsed.events);if(!active&&validActive(parsed.active,id=>Q.has(id)))active=parsed.active}else if(legacyValid(parsed)){const signature=JSON.stringify([parsed.xp,parsed.seq,parsed.lessons]);if(!state.events.some(e=>e.kind==='import'&&JSON.stringify([e.payload.xp,e.payload.seq,e.payload.lessons])===signature))state.events.push(event('import',parsed))}else throw Error('This is not a recognised Lawlingo progress backup.');save();render();toast('Your progress is imported. Existing answers were kept.')}catch(e){toast(e.message)}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();const action=el.dataset.action,id=el.dataset.id;switch(action){case'pet':petLegalu();break;case'bonus':startBonus();break;case'sampletimed':begin(Array.from({length:50},(_,i)=>`sample-${i+1}`),'Official HEC sample · historical edition','mock',null,60);break;case'guide':guideSubject=id;navigate('guide');break;case'paper':await startPaper(id);break;case'repairsubject':if(summary?.items)begin(summary.items.filter(i=>Q.get(i.qid)?.subject===id&&i.choice!==(i.answer??Q.get(i.qid)?.answer)).map(i=>i.qid),B.subjects[id].name+' · mock repair');break;case'hint':active.guessed=true;active.hint=true;save();session();break;case'quick':quickSession();break;case'mockresult':{const m=P.mocks.find(x=>x.id===id);if(m){summary={...m,mode:'mock'};navigate('result')}break}case'mockmistakes':if(summary?.items)begin(summary.items.filter(i=>i.choice!==(i.answer??Q.get(i.qid)?.answer)).map(i=>i.qid).filter(id=>Q.has(id)),'Mock mistake repair');break;case'nextlesson':{const l=nextLesson();if(l)beginLesson(l.id);else navigate('review');break}case'nav':navigate(el.dataset.view);break;case'day':chosenDay=+el.dataset.day;render();break;case'lesson':beginLesson(id);break;case'resume':navigate('session');break;case'pause':save();navigate('home');break;case'startquestions':active.phase='question';save();session();break;case'subject':{const qs=BOOK.filter(q=>q.subject===id).sort((a,b)=>(s(a.id).seen?1:0)-(s(b.id).seen?1:0)||s(a.id).level-s(b.id).level);begin(qs.slice(0,20).map(q=>q.id),B.subjects[id].name+' · book practice');break}case'foundation':{const qs=shuffle(B.questions.filter(q=>q.subject===id&&q.sourceType==='foundation')).slice(0,15);await begin(qs.map(q=>q.id),B.subjects[id].name+' · foundations');break}case'due':begin(shuffle(due()).slice(0,20).map(q=>q.id),'Spaced recall');break;case'weak':begin(shuffle(weak().filter(q=>q.answer!==null)).slice(0,20).map(q=>q.id),'Mistake repair');break;case'single':begin([id],'One small repair');break;case'choice':if(!active||active.phase==='feedback')break;if(active.mode==='mock')active.choices[qAt().id]=+el.dataset.choice;else active.choice=+el.dataset.choice;save();session();main.querySelector('[data-action="choice"][data-choice="'+el.dataset.choice+'"]')?.focus({preventScroll:true});break;case'check':check();break;case'next':advance();break;case'bookmark':add('bookmark',{qid:qAt().id,on:!P.bookmarks.has(qAt().id)});session();break;case'readaloud':if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(qAt().explanation+' '+qAt().cue);u.lang='en-GB';u.rate=.9;speechSynthesis.speak(u)}else toast('Read-aloud is unavailable in this browser.');break;case'startmock':startMock(100);break;case'shortmock':startMock(20);break;case'previous':if(active.index>0){active.index--;save();session()}break;case'mocknext':if(active.index<active.ids.length-1){active.index++;save();session();window.scrollTo(0,0)}else submitMock();break;case'jump':active.index=+el.dataset.index;save();session();window.scrollTo(0,0);break;case'submitmock':submitMock();break;case'sample':begin(Array.from({length:50},(_,i)=>`sample-${i+1}`),'HEC official sample','sample');break;case'export':exportProgress();break;}});
document.addEventListener('change',e=>{if(e.target.id==='guessed'){active.guessed=active.hint||e.target.checked;save()}if(['largeText','reduceMotion'].includes(e.target.id)){state.settings[e.target.id]=e.target.checked;save();render()}if(e.target.id==='sound'){state.settings.sound=e.target.checked;save();chime()}if(e.target.id==='import'&&e.target.files[0])importProgress(e.target.files[0])});
document.addEventListener('keydown',e=>{
 if(view!=='session'||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||document.querySelector('.modal-backdrop'))return;
 if(/^[1-4]$/.test(e.key)){e.preventDefault();[...main.querySelectorAll('[data-action="choice"]')][+e.key-1]?.click()}
 if(e.key==='Enter'&&(document.activeElement===main||document.activeElement?.closest('.feedback')||document.activeElement?.matches('[data-action="choice"]'))){e.preventDefault();main.querySelector('[data-action="check"],[data-action="next"]')?.click()}
});
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const incoming=JSON.parse(e.newValue);if(validate(incoming)&&incoming.owner===state.owner){state.events=merge(state.events,incoming.events);P=derive(state.events);header();if(view!=='session')render()}}catch{}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateTimer()}});
setInterval(updateTimer,1000);
save();render();
if(recoveredSave)toast('Your progress was restored from the automatic recovery copy. Export a backup after this session.');
window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(['home','subjects','review','mock','sources','progress','session','library'].includes(target)){view=target;render();main.focus({preventScroll:true})}});
function quickSession(){
 const candidates=[...due().sort((a,b)=>s(a.id).due-s(b.id).due),...shuffle(weak().filter(canAnswer)),...shuffle(BOOK.filter(q=>graded(q)&&!s(q.id).seen))];
 const ids=[...new Set(candidates.map(q=>q.id))].slice(0,10);begin(ids,'Ten-question warm-up');
}
function library(){
 main.innerHTML=`<div class="eyebrow">YOUR BOOK, EASY TO FIND</div><h1 style="margin-top:10px">Question library</h1><p class="muted">Search a rule, provision or phrase. Practise any question, or open its original page.</p><section class="card"><div class="library-controls"><label>Search<input type="search" id="library-search" class="input" placeholder="e.g. res judicata, Article 17" value="${esc(libraryFilter.text)}"></label><label>Subject<select id="library-subject" class="input"><option value="all">All subjects</option>${Object.entries(B.subjects).map(([id,v])=>`<option value="${id}" ${libraryFilter.subject===id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><label>Show<select id="library-status" class="input">${[['all','All book questions'],['verified','Verified answers'],['saved','My bookmarks'],['unseen','Not practised yet']].map(([id,label])=>`<option value="${id}" ${libraryFilter.status===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div id="library-results" aria-live="polite"></div></section>`;libraryResults();
}
function libraryResults(){
 const terms=libraryFilter.text.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);
 const rows=BOOK.filter(q=>(libraryFilter.subject==='all'||q.subject===libraryFilter.subject)&&(libraryFilter.status==='all'||libraryFilter.status==='verified'&&graded(q)||libraryFilter.status==='saved'&&P.bookmarks.has(q.id)||libraryFilter.status==='unseen'&&!s(q.id).seen)&&terms.every(term=>(q.question+' '+q.reference+' '+q.subject+' '+q.number).toLocaleLowerCase().includes(term)));
 const target=document.getElementById('library-results');if(!target)return;target.innerHTML=`<p class="source-note">${rows.length} matches${rows.length>60?' · showing the first 60; narrow your search for more':''}</p>${rows.slice(0,60).map(q=>`<article class="review-item"><div class="row between"><span class="badge">${esc(q.subject)} Q${q.number}</span><span class="badge ${graded(q)?'verified':'warn'}">${esc(q.status)}</span></div><p style="margin-top:10px">${esc(q.question)}</p><div class="row">${button('single','Practise question','',`data-id="${q.id}"`)}<a href="book-pages/${String(q.page).padStart(2,'0')}.png" target="_blank" rel="noopener">Original page ↗</a></div></article>`).join('')||'<div class="empty">No matching questions. Try a shorter phrase or another subject.</div>'}`;
}
document.addEventListener('input',e=>{if(e.target.id==='library-search'){libraryFilter.text=e.target.value;libraryResults()}});
document.addEventListener('change',e=>{if(e.target.id==='library-subject'){libraryFilter.subject=e.target.value;libraryResults()}if(e.target.id==='library-status'){libraryFilter.status=e.target.value;libraryResults()}});

function syllabusPanel(){const eligible=BOOK.filter(mockEligible);return `<section class="card"><h2>What these mocks cover</h2><p>${eligible.length} book questions currently pass all three checks: verified answer, syllabus scope and four distinct options. The full 604-question book remains in the lessons.</p><details class="review-item"><summary>See the subject and topic map</summary>${Object.entries(B.subjects).map(([id,o])=>{const qs=eligible.filter(q=>q.subject===id);return `<p><strong>${esc(o.name)} · ${o.weight}/100 marks · ${qs.length} eligible questions</strong><br>${[...new Set(qs.map(q=>q.syllabusTopic))].map(esc).join(' · ')}</p>`}).join('')}</details><div class="notice"><strong>Coverage gap to keep in mind:</strong> only six Islamic Jurisprudence book answers are independently verified. Repeated success on those six does not establish mastery of the whole Nyazee syllabus. Use the Islamic subject guide and your guidebook alongside the flagged book lessons.</div><p class="source-note">The official sample is the closest wording reference available here. Book stems may be condensed; each has an original-page link. Older constitutional sample questions retain their historical key with explanatory notes. Timed sample mode uses 60 minutes as a practice choice.</p><a href="https://www.hec.gov.pk/english/services/students/etc/Documents/Curriculum-LAW-GAT-test.pdf" target="_blank" rel="noopener">HEC syllabus</a> · <a href="https://www.hec.gov.pk/english/services/students/etc/Documents/LAW%20GAT%20Sample%20Paper.pdf" target="_blank" rel="noopener">HEC original sample paper</a></section>`}

function readinessNote(items){const first=items.filter(i=>i.priorSeen===false),known=items.filter(i=>i.priorSeen===true);return `<div class="callout">${first.length+known.length===items.length?`Questions not previously answered in this app: <strong>${first.filter(i=>i.choice===(i.answer??Q.get(i.qid)?.answer)).length}/${first.length}</strong>. Previously practised: ${known.length}. `:''}This is a practice score, not an exam prediction. Repeated questions and overlapping concepts can make a familiar paper easier.</div>`}

function memoryHTML(q){const cue=conciseCue(q);return cue?`<p class="memory">${esc(cue)}</p>`:''}
function petLegalu(){
 state.settings.legaluTaps=(state.settings.legaluTaps||0)+1;save();
 const lines=['Cock-a-doodle-court! Read the rule before choosing the letter.','Legalu objects… to skipping your breaks. Stretch, then return.','Tiny victory: explain one rule aloud in your own words.','The golden egg is on My path: three questions, double XP for confident recall.','Case closed? Try explaining why the other options are wrong.'];
 toast(lines[(state.settings.legaluTaps-1)%lines.length]);celebrate();
}
async function startBonus(){
 if(state.settings.bonusCompletedDay===dayKey()){toast('Golden egg collected today. It returns tomorrow; your regular reviews are ready.');return}
 if(active?.bonus){navigate('session');return}
 const done=new Set(state.events.filter(e=>e.kind==='answer'&&e.payload.bonus&&dayKey(Date.parse(e.occurred_at))===dayKey()).map(e=>e.payload.qid));
 if(done.size>=3){toast('Today’s three bonus questions are already collected. Come back tomorrow!');return}
 const pool=BOOK.filter(q=>mockEligible(q)&&!done.has(q.id)&&(!s(q.id).last||Date.now()>=s(q.id).due));
 const ids=shuffle(pool).slice(0,3-done.size).map(q=>q.id);
 if(!ids.length){toast('Let your recall rest. More bonus questions will become available later.');return}
 if(await begin(ids,'Legalu’s golden egg · 3-question quest')){active.bonus=true;save();session()}
}
